fn encode_cyclic(s: Vec<i8>) -> Vec<i8> {
    let n = s.len();
    // Allocate the result vector with the same length as the input.
    let mut res = Vec::with_capacity(n);

    // Process all full blocks of three elements.
    let end_full_block = n - (n % 3);
    for i in (0..end_full_block).step_by(3) {
        // For each block [a, b, c], push [b, c, a].
        res.push(s[i + 1]);
        res.push(s[i + 2]);
        res.push(s[i]);
    }

    // Copy any remaining elements (0, 1, or 2) unchanged.
    for i in end_full_block..n {
        res.push(s[i]);
    }

    res
}